/**
 * Host link credentials on disk (ADR 0330). `agent-host-cli enroll` writes
 * `<data-dir>/agent-host-cli/gateway-link.json` with mode 0600 and an atomic
 * rename; `--gateway` reads it back at startup. The private key is generated by
 * the Host and never leaves this file.
 */
import { mkdir, readFile, rename, unlink, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";

import type { HostLinkCredentials } from "@minih-agent/racp";

const FILE_MODE = 0o600;

export class GatewayLinkError extends Error {
  readonly code = "GATEWAY_LINK_INVALID";

  constructor(message: string) {
    super(message);
    this.name = "GatewayLinkError";
  }
}

export function gatewayLinkPath(dataDir: string): string {
  return join(dataDir, "agent-host-cli", "gateway-link.json");
}

function isCredentials(value: unknown): value is HostLinkCredentials {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return ["hostId", "gatewayUrl", "gatewayCaPem", "certificatePem", "privateKeyPem", "expiresAt"].every(
    (key) => typeof candidate[key] === "string" && (candidate[key] as string).length > 0,
  );
}

/** `null` when this Host was never enrolled; a typed error when the file is corrupt. */
export async function readGatewayLink(dataDir: string): Promise<HostLinkCredentials | null> {
  const path = gatewayLinkPath(dataDir);
  let text: string;
  try {
    text = await readFile(path, "utf8");
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
    throw error;
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(text) as unknown;
  } catch {
    throw new GatewayLinkError(`${path} is not valid JSON; run \`agent-host-cli enroll\` again`);
  }
  if (!isCredentials(parsed)) {
    throw new GatewayLinkError(`${path} is missing fields; run \`agent-host-cli enroll\` again`);
  }
  return parsed;
}

export async function writeGatewayLink(dataDir: string, credentials: HostLinkCredentials): Promise<string> {
  const path = gatewayLinkPath(dataDir);
  await mkdir(dirname(path), { recursive: true, mode: 0o700 });
  const temporary = `${path}.${process.pid}.tmp`;
  await writeFile(temporary, `${JSON.stringify(credentials, null, 2)}\n`, { encoding: "utf8", mode: FILE_MODE });
  await rename(temporary, path);
  return path;
}

export async function removeGatewayLink(dataDir: string): Promise<void> {
  await unlink(gatewayLinkPath(dataDir)).catch((error: unknown) => {
    if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
  });
}
